extracted_python_code:
frequently_bought_stocks = Tickers.CALCULATE(
    ticker_symbol=symbol,
    num_buy_transactions=COUNT(
        transactions_of.WHERE(
            (DATEDIFF("days", date_time, DATETIME('now')) <= 10) & 
            (transaction_type == "buy")
        )
    )
).TOP_K(2, by=num_buy_transactions.DESC())

activity_ratio_by_country = Customers.WHERE(
    (YEAR(join_date) == 2022) & (HAS(transactions_made) == 1)
).PARTITION(name="countries", by=(country)).CALCULATE(
    country=country,
    num_active_customers=COUNT(Customers.WHERE(status == 'active')),
    total_customers=COUNT(Customers)
).CALCULATE(
    country=country,
    AR=IFF(total_customers > 0, (num_active_customers / total_customers) * 100.0, 0.0)
)

result = Broker.CALCULATE(
    customer_count=COUNT(
        Customers.WHERE(
            (
                STARTSWITH(LOWER(name), 'j') | ENDSWITH(LOWER(name), 'ez')
            ) & 
            ENDSWITH(LOWER(state), 'a')
        )
    )
)

buy_customer_ids = Transactions.WHERE(transaction_type == 'buy').PARTITION(name="customers", by=(customer_id)).CALCULATE(
    customer_id=customer_id
)

result = Tickers.WHERE(
    HAS(historical_prices.WHERE(date >= "2023-04-01")) == 1
).CALCULATE(
    ticker_id=_id
)

result = Broker.CALCULATE(
    lowest_price=MIN(
        DailyPrices.WHERE(
            (ticker.symbol == 'VTI') & (DATEDIFF("days", date, 'now') <= 7)
        ).close
    )
)

result = Broker.CALCULATE(
    num_transactions=COUNT(
        Customers.WHERE(
            DATEDIFF("days", join_date, DATETIME('now')) <= 70
        ).transactions_made
    )
)

monthly_average_prices = Transactions.WHERE(
    (status == 'success') &
    (YEAR(date_time) == 2023) &
    (MONTH(date_time) <= 3)
).CALCULATE(
    month=MONTH(date_time)
).PARTITION(
    name="monthly_transactions",
    by=(month)
).CALCULATE(
    month=month,
    average_price=AVG(Transactions.price)
).ORDER_BY(month.ASC())

sales_by_model = Cars.WHERE(
    LIKE(UPPER(vin_number), '%M5%')
).PARTITION(
    name="model_group", by=(make, model)
).CALCULATE(
    make=make,
    model=model,
    number_of_sales=COUNT(Cars.sale_records)
)

result = Dealership.CALCULATE(
    asp=AVG(Sales.WHERE((YEAR(sale_date) == 2023) & (MONTH(sale_date) <= 3)).sale_price)
)

result = Dealership.CALCULATE(
    average_days_to_payment=ROUND(
        AVG(
            PaymentsReceived.CALCULATE(
                days_to_pay=DATEDIFF("days", sale_record.sale_date, payment_date)
            ).days_to_pay
        ),
        2
    )
)

result = Customers.WHERE(HAS(car_purchases) == 1).CALCULATE(
    customer_id=_id
)

salespersons_with_cash_payments = Salespersons.WHERE(
    HAS(sales_made.payment.WHERE(payment_method == 'Cash')) == 1
).CALCULATE(
    salesperson_id=_id
)

quarterly_sales_by_state = Sales.WHERE(YEAR(sale_date) == 2023).CALCULATE(
    customer_state=customer.state,
    quarter_date=IFF(
        MONTH(sale_date) <= 3, DATETIME(sale_date, 'start of year'),
        IFF(
            MONTH(sale_date) <= 6, DATETIME(DATETIME(sale_date, 'start of year'), '+ 3 months'),
            IFF(
                MONTH(sale_date) <= 9, DATETIME(DATETIME(sale_date, 'start of year'), '+ 6 months'),
                DATETIME(DATETIME(sale_date, 'start of year'), '+ 9 months')
            )
        )
    )
).PARTITION(
    name="state_quarters",
    by=(customer_state, quarter_date)
).CALCULATE(
    state=customer_state,
    quarter=quarter_date,
    total_quarterly_sales=SUM(Sales.sale_price)
)

result = DermTreatment.CALCULATE(
    num_patients=COUNT(
        Patients.WHERE(
            ENDSWITH(email, "@gmail.com") | ENDSWITH(email, "@yahoo.com")
        )
    )
)

result = DermTreatment.CALCULATE(
    patient_count=COUNT(
        Patients.WHERE(
            HAS(
                treatments_received.WHERE(
                    (diagnosis.diag_name == 'Psoriasis vulgaris') & (drug.drug_type == 'biologic')
                )
            ) == 1
        )
    )
)

alice_treatments_count = DermTreatment.CALCULATE(
    start_of_current_month=DATETIME('now', 'start of month'),
    start_of_range=DATETIME('now', 'start of month', '-6 months')
).Patients.WHERE(
    first_name == "Alice"
).CALCULATE(
    num_treatments=COUNT(treatments_received.WHERE(
        (start_dt >= start_of_range) & (start_dt < start_of_current_month)
    ))
)

result = DermTreatment.CALCULATE(
    average_weight=AVG(Drugs.WHERE(drug_name == 'Drugalin').treatments_used_in.patient.weight_kg)
)

caw_for_male_patients = DermTreatment.CALCULATE(
    caw=AVG(Patients.WHERE(gender == 'Male').weight_kg)
)

npi_by_year = Patients.CALCULATE(
    first_treatment_year=YEAR(MIN(treatments_received.start_dt))
).PARTITION(
    name="yearly_new_patients", by=(first_treatment_year)
).CALCULATE(
    year=first_treatment_year,
    num_new_patients=COUNT(Patients)
).CALCULATE(
    year=year,
    num_new_patients=num_new_patients,
    NPI=num_new_patients - PREV(num_new_patients, by=year.ASC())
).ORDER_BY(year.ASC())

pic_count = DermTreatment.CALCULATE(
    pic_female_patients=COUNT(Patients.WHERE((gender == 'female') & (ins_type == 'private')))
)

top_drug_by_adverse_events = Drugs.CALCULATE(
    drug_id=drug_id,
    drug_name=drug_name,
    num_adverse_events=COUNT(
        treatments_used_in.adverse_events.WHERE(
            (YEAR(reported_dt) == YEAR(treatment.start_dt)) & 
            (MONTH(reported_dt) == MONTH(treatment.start_dt))
        )
    )
).TOP_K(1, by=num_adverse_events.DESC())

result = Doctors.WHERE(
    HAS(prescribed_treatments.WHERE(drug.drug_type == "Biologic")) == 1
).PARTITION(name="states", by=(loc_state,)).CALCULATE(
    state=loc_state
)

result = Diagnoses.WHERE(
    HAS(treatments_for.outcome_records) == 1
).CALCULATE(
    diagnosis_name=diag_name,
    max_itch_score=MAX(treatments_for.outcome_records.day100_itch_vas),
    num_patients=NDISTINCT(treatments_for.patient.patient_id)
).TOP_K(
    3, by=max_itch_score.DESC()
)

top_specialties_by_drug_amount = Treatments.WHERE(
    DATEDIFF("months", start_dt, DATETIME('now')) < 6
).CALCULATE(
    speciality=doctor.speciality
).PARTITION(
    name="specialty_groups", by=(speciality)
).CALCULATE(
    speciality=speciality,
    number_of_treatments=COUNT(Treatments),
    total_drug_amount=SUM(Treatments.tot_drug_amt)
).TOP_K(3, by=total_drug_amount.DESC())

result = DermTreatment.CALCULATE(
    avg_patient_age=ROUND(
        AVG(
            Patients.WHERE((gender == 'male') & (ins_type == 'private')).CALCULATE(
                age=DATEDIFF("years", date_of_birth, DATETIME('now'))
            ).age
        ),
        0
    )
)

average_amb_past_week = Ewallet.CALCULATE(
    average_balance=AVG(
        UserBalances.WHERE(
            DATEDIFF("days", updated_at, DATETIME('now')) <= 7
        ).PARTITION(
            name="user_groups", by=(user_id)
        ).CALCULATE(
            user_amb=AVG(UserBalances.balance)
        ).user_amb
    )
)

user_session_duration_analysis = Users.CALCULATE(
    user_id=uid,
    total_duration=SUM(
        sessions.WHERE(
            (session_start_ts >= "2023-06-01") & (session_start_ts < "2023-06-08")
        ).CALCULATE(
            duration=DATEDIFF("seconds", session_start_ts, session_end_ts)
        ).duration
    )
).WHERE(
    total_duration > 0
).ORDER_BY(
    total_duration.DESC()
)

us_users_with_unread_promos = Users.WHERE(
    (LOWER(country) == 'us') &
    (HAS(notifications.WHERE((status == 'unread') & (notification_type == 'promotional'))) == 1)
).CALCULATE(
    username=username,
    total_unread_promotional_notifications=COUNT(
        notifications.WHERE((status == 'unread') & (notification_type == 'promotional'))
    )
)

merchant_ids_received_money = Transactions.WHERE(receiver_type == 1).PARTITION(name="merchants", by=(receiver_id)).CALCULATE(
    mid=receiver_id
)

# Find merchants whose earliest coupon was created within a year of registration
result = Merchants.WHERE(HAS(coupons) == 1).CALCULATE(
    merchant_id=mid,
    registration_date=created_at,
    earliest_coupon_id=coupons.WHERE(
        RANKING(by=start_date.ASC(), per="Merchants") == 1
    ).SINGULAR().cid,
    earliest_coupon_start_date=coupons.WHERE(
        RANKING(by=start_date.ASC(), per="Merchants") == 1
    ).SINGULAR().start_date
).WHERE(
    DATEDIFF("days", registration_date, earliest_coupon_start_date) <= 365
)

result = Users.WHERE(
    HASNOT(
        notifications.WHERE(
            DATEDIFF("days", Users.created_at, created_at) <= 365
        )
    ) == 1
).CALCULATE(
    username=username,
    email=email,
    signup_date=created_at
)
